package com.telehealth.network.controller;

import com.telehealth.network.document.TelehealthConsultationDoc;
import com.telehealth.network.dto.ClinicalNotesUpdateDto;
import com.telehealth.network.security.DoctorPrincipal;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;
import org.springframework.data.mongodb.core.query.Update;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/mongo/consultations")
public class ConsultationUpdateController {

    private final MongoTemplate mongoTemplate;

    public ConsultationUpdateController(MongoTemplate mongoTemplate) {
        this.mongoTemplate = mongoTemplate;
    }

    @PutMapping("/{consultationId}/clinical-notes")
    public ResponseEntity<String> updateClinicalNotes(
            @PathVariable String consultationId,
            @RequestBody ClinicalNotesUpdateDto dto,
            @AuthenticationPrincipal DoctorPrincipal doctor) {
        Query query = new Query(new Criteria().andOperator(
                Criteria.where("_id").is(consultationId),
                Criteria.where("attendingPhysicianId").is(doctor.getId())
        ));
        Update update = new Update()
                .set("clinicalNotes", dto.getNotes())
                .set("prescriptionRef", dto.getPrescriptionRef());
        TelehealthConsultationDoc doc = mongoTemplate.findAndModify(query, update, TelehealthConsultationDoc.class);
        if (doc == null) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Consultation not found or not assigned to physician");
        }
        return ResponseEntity.ok("Clinical notes updated");
    }
}
